/** Le genre que l'étagère Vinted `id` porte — null si elle n'en porte aucun. */
export function brancheVinted(id: unknown): string | null {
  const n = Number(id);
  return Number.isFinite(n) && BRANCHE[n] ? BRANCHE[n] : null;
}

